import json
import re
from typing import Dict, List, Tuple

SECTION_RE = re.compile(r"^\s*\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.+)$")


def _split_arrow(line: str) -> Tuple[str, str]:
    if "->" not in line:
        raise ValueError(f"Missing '->' in line: {line}")
    left, right = line.rsplit("->", 1)
    return left.strip(), right.strip()


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip():
            continue
        m = SECTION_RE.match(line)
        if m:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = m.group(1).strip()
            current_lines = []
            continue
        if current_id is None:
            raise ValueError(f"Line outside of section: {line}")
        current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for node_id, lines in sections:
        if not lines:
            node_type = "line"
            node_text = ""
            speaker = ""
        else:
            has_choice = any(CHOICE_RE.match(l) for l in lines)
            if has_choice:
                node_type = "choice"
                speaker = ""
                choice_texts: List[str] = []
                for line in lines:
                    m = CHOICE_RE.match(line)
                    if not m:
                        continue
                    left, target = _split_arrow(m.group(2))
                    choice_text = left.strip()
                    choice_texts.append(choice_text)
                    edges.append({"from": node_id, "to": target, "text": choice_text})
                node_text = "\n".join(choice_texts)
            else:
                node_type = "line"
                speaker = ""
                texts: List[str] = []
                for line in lines:
                    left, target = _split_arrow(line)
                    if ":" not in left:
                        raise ValueError(f"Missing speaker in line: {line}")
                    spk, text_part = left.split(":", 1)
                    spk = spk.strip()
                    text_part = text_part.strip()
                    if not speaker:
                        speaker = spk
                    texts.append(text_part)
                    edges.append({"from": node_id, "to": target, "text": text_part})
                node_text = "\n".join(texts)
        nodes.append({"id": node_id, "text": node_text, "speaker": speaker, "type": node_type})

    return {"nodes": nodes, "edges": edges}


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        raise ValueError("No nodes parsed")

    node_ids = {n["id"] for n in nodes}

    # Edge target validation
    for edge in edges:
        target = edge["to"]
        if target not in node_ids and target != "End":
            raise ValueError(f"Edge target does not exist: {edge}")

    # Reachability from first node
    start_id = nodes[0]["id"]
    adjacency: Dict[str, List[str]] = {}
    for edge in edges:
        adjacency.setdefault(edge["from"], []).append(edge["to"])

    seen = set()
    stack = [start_id]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adjacency.get(cur, []):
            if nxt in node_ids:
                stack.append(nxt)
    unreachable = [n for n in node_ids if n not in seen]
    if unreachable:
        raise ValueError(f"Unreachable nodes found: {sorted(unreachable)}")


def _dot_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _write_dot(graph: Dict[str, List[Dict[str, str]]], path: str) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    lines = ["digraph Dialogue {", "  node [shape=box];"]
    for node in nodes:
        label = node["id"]
        if node.get("type") == "line" and node.get("speaker"):
            label = f"{label}\\n{node['speaker']}: {node['text']}"
        lines.append(f"  \"{_dot_escape(node['id'])}\" [label=\"{_dot_escape(label)}\"];" )
    for edge in edges:
        lines.append(
            f"  \"{_dot_escape(edge['from'])}\" -> \"{_dot_escape(edge['to'])}\" "
            f"[label=\"{_dot_escape(edge['text'])}\"];"
        )
    lines.append("}")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()
    graph = parse_script(text)
    _validate_graph(graph)
    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
    _write_dot(graph, "/app/dialogue.dot")


if __name__ == "__main__":
    main()
